test_that("student distribution works correctly", {
  withr::local_seed(3L)
  brms_port("distributions:4", "pass",
    "",
    expect_equal(integrate(dstudent_t, -100, 100, df = 15, mu = 10, 
        sigma = 5)$value, 1)
  )
  brms_port("distributions:5", "pass",
    "",
    expect_equal(dstudent_t(1, df = 10, mu = 0, sigma = 5), dt(1/5, df = 10)/5)
  )
  brms_port("distributions:6", "pass",
    "",
    expect_equal(pstudent_t(2, df = 20, mu = 2, sigma = 0.4), pt(0, df = 20))
  )
  brms_setup("distributions:7",
    ps <- c(-1,0,0.7,1,1.5)
  )
  brms_port("distributions:8", "cannot transfer",
    paste0(
      "decision: brms's q function; no frmtmb family object ",
      "carries a quantile function, and SPEC.md:153-154 puts ",
      "numeric d/p/q/r functions for post-processing outside ",
      "frmtmb, in gamlss.dist or extraDistr"),
    SW(expect_equal(qstudent_t(ps, df = 5, mu = 2, sigma = 3), 2 + 
        3 * qt(ps, df = 5)))
  )
  brms_port("distributions:9", "pass",
    "",
    expect_equal(length(rstudent_t(10, df = 10, mu = rnorm(10), sigma = 1:10)), 
        10)
  )
})

