test_that("d<ordinal_family>() works correctly", {
  withr::local_seed(235L)
  brms_setup("distributions:236",
    source(identity(file.path(brms_adapt_suite_dir, "helpers", "inv_link_ordinal_ch.R")))
  )
  brms_setup("distributions:237",
    source(identity(file.path(brms_adapt_suite_dir, "helpers", "simopts_catlike_oneobs.R")))
  )
  brms_port("distributions:238", "divergence",
    paste0(
      "brms's block draws its thresholds unsorted (rnorm), and at ",
      "a decreasing pair brms's dcumulative() returns a NEGATIVE ",
      "category probability (4 of 20 cells at seed 238), which its ",
      "closed-form helper reproduces; frmtmb's cumulative builds ",
      "the categories from the threshold gaps and returns NaN with ",
      "a warning, in categories on either side of the decreasing ",
      "pair (at draw 5 of bin2-probe3.txt categories 1 and 2 are ",
      "NaN where brms's category 1 is 0.805). With sorted ",
      "thresholds every cell agrees, and sratio, cratio and acat ",
      "agree everywhere, to 2.2e-16 or better ",
      "(dev/remeasure-bin2-probe3.R, log ",
      "dev/remeasure-out/probe/bin2-probe3.txt). A fit never ",
      "reaches decreasing thresholds: frmtmb's threshold map ",
      "orders them"),
    for (ndraws in ndraws_vec) {
        for (ncat in ncat_vec) {
            thres_test <- matrix(rnorm(ndraws * (ncat - 1)), nrow = ndraws)
            eta_test_list <- list(rnorm(ndraws), matrix(rnorm(ndraws * 
                (ncat - 1)), nrow = ndraws))
            for (eta_test in eta_test_list) {
                thres_eta <- if (is.matrix(eta_test)) {
                    stopifnot(identical(dim(eta_test), dim(thres_test)))
                    thres_test - eta_test
                }
                else {
                    sweep(thres_test, 1, as.array(eta_test))
                }
                eta_thres <- if (is.matrix(eta_test)) {
                    stopifnot(identical(dim(eta_test), dim(thres_test)))
                    eta_test - thres_test
                }
                else {
                    sweep(-thres_test, 1, as.array(eta_test), FUN = "+")
                }
                for (link in c("logit", "probit", "cauchit", "cloglog")) {
                    d_cumul <- brms_adapt_dord("cumulative", seq_len(ncat), 
                      eta_test, thres_test, link = link)
                    d_cumul_ch <- inv_link_cumulative_ch(thres_eta, 
                      link = link)
                    expect_equivalent(d_cumul, d_cumul_ch)
                    expect_equal(dim(d_cumul), c(ndraws, ncat))
                    d_sratio <- brms_adapt_dord("sratio", seq_len(ncat), 
                      eta_test, thres_test, link = link)
                    d_sratio_ch <- inv_link_sratio_ch(thres_eta, 
                      link = link)
                    expect_equivalent(d_sratio, d_sratio_ch)
                    expect_equal(dim(d_sratio), c(ndraws, ncat))
                    d_cratio <- brms_adapt_dord("cratio", seq_len(ncat), 
                      eta_test, thres_test, link = link)
                    d_cratio_ch <- inv_link_cratio_ch(eta_thres, 
                      link = link)
                    expect_equivalent(d_cratio, d_cratio_ch)
                    expect_equal(dim(d_cratio), c(ndraws, ncat))
                    d_acat <- brms_adapt_dord("acat", seq_len(ncat), 
                      eta_test, thres_test, link = link)
                    d_acat_ch <- inv_link_acat_ch(eta_thres, link = link)
                    expect_equivalent(d_acat, d_acat_ch)
                    expect_equal(dim(d_acat), c(ndraws, ncat))
                }
            }
        }
    }
  )
})

test_that("inv_link_<ordinal_family>() works correctly for arrays", {
  withr::local_seed(297L)
  brms_setup("distributions:298",
    source(identity(file.path(brms_adapt_suite_dir, "helpers", "inv_link_ordinal_ch.R")))
  )
  brms_setup("distributions:299",
    source(identity(file.path(brms_adapt_suite_dir, "helpers", "simopts_catlike.R")))
  )
  brms_port("distributions:300", "divergence",
    paste0(
      "the statement is one loop of 8 assertions; recorded whole ",
      "it does not hold, and dev/brmsport-bin2-split.tsv gives ",
      "each line its verdict: brms's block draws its array x = ",
      "thres - eta unsorted (rnorm), so for cumulative a ",
      "decreasing pair gives brms's inv_link_cumulative() a ",
      "NEGATIVE probability, which frmtmb's cumulative returns as ",
      "NaN: the identity holds in 16 of 32 iterations, the ",
      "ordered-threshold domain limit of distributions:238. A fit ",
      "never reaches decreasing thresholds"),
    for (ndraws in ndraws_vec) {
      for (nobsv in nobsv_vec) {
        for (ncat in ncat_vec) {
          x_test <- array(rnorm(ndraws * nobsv * (ncat - 1)),
                          dim = c(ndraws, nobsv, ncat - 1))
          nx_test <- -x_test
          for (link in c("logit", "probit", "cauchit", "cloglog")) {
            # cumulative():
            il_cumul <- inv_link_cumulative(x_test, link = link)
            il_cumul_ch <- inv_link_cumulative_ch(x_test, link = link)
            expect_equivalent(il_cumul, il_cumul_ch)
            expect_equal(dim(il_cumul), c(ndraws, nobsv, ncat))
    
            # sratio():
            il_sratio <- inv_link_sratio(x_test, link = link)
            il_sratio_ch <- inv_link_sratio_ch(x_test, link = link)
            expect_equivalent(il_sratio, il_sratio_ch)
            expect_equal(dim(il_sratio), c(ndraws, nobsv, ncat))
    
            # cratio():
            il_cratio <- inv_link_cratio(nx_test, link = link)
            il_cratio_ch <- inv_link_cratio_ch(nx_test, link = link)
            expect_equivalent(il_cratio, il_cratio_ch)
            expect_equal(dim(il_cratio), c(ndraws, nobsv, ncat))
    
            # acat():
            il_acat <- inv_link_acat(nx_test, link = link)
            il_acat_ch <- inv_link_acat_ch(nx_test, link = link)
            expect_equivalent(il_acat, il_acat_ch)
            expect_equal(dim(il_acat), c(ndraws, nobsv, ncat))
          }
        }
      }
    }
  )
})

test_that("dsratio() and dcratio() give the same results for symmetric distribution functions", {
  withr::local_seed(441L)
  brms_setup("distributions:445",
    source(identity(file.path(brms_adapt_suite_dir, "helpers", "simopts_catlike_oneobs.R")))
  )
  brms_port("distributions:446", "pass",
    "",
    for (ndraws in ndraws_vec) {
        for (ncat in ncat_vec) {
            thres_test <- matrix(rnorm(ndraws * (ncat - 1)), nrow = ndraws)
            eta_test_list <- list(rnorm(ndraws), matrix(rnorm(ndraws * 
                (ncat - 1)), nrow = ndraws))
            for (eta_test in eta_test_list) {
                for (link in c("logit", "probit", "cauchit", "cloglog")) {
                    d_sratio <- brms_adapt_dord("sratio", seq_len(ncat), 
                      eta_test, thres_test, link = link)
                    d_cratio <- brms_adapt_dord("cratio", seq_len(ncat), 
                      eta_test, thres_test, link = link)
                    if (link != "cloglog") {
                      expect_equal(d_sratio, d_cratio)
                    }
                    else {
                      expect_false(isTRUE(all.equal(d_sratio, d_cratio)))
                    }
                }
            }
        }
    }
  )
})

